#include "../port/device_access.h"
extern void queue_copy_temperature(int temperature_dC);
extern int calibrate_temperature(int raw);
void acquire_once(void)
{
    int raw = (int)device_registers()->sample;
    queue_copy_temperature(calibrate_temperature(raw));
}

